INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T1', 1, E'mystery', E'수수께끼', E'Gol D. Roger''s hidden treasure', E'Gol D. Roger''s hidden treasure — he claimed to have left it all behind, but a seeker would have to search the entire world for it; its location is unknown.', E'Gol D. Roger', E'Gol D. Roger''s hidden treasure — he claimed to have left it all behind, but a seeker would have to search the entire world for it; its location is unknown.', E'V1', E'Gol D. Roger is publicly executed; his final words about leaving all his treasure behind spark the Great Pirate Era.', E'open', NULL, NULL, E't1gold.roger''shiddentreasuregold.roger''shiddentreasure—heclaimedtohaveleftitallbehind,butaseekerwouldhavetosearchtheentireworldforit;itslocationisunknown.gold.roger수수께끼1화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T2', 1, E'promise', E'약속', E'Shanks entrusts his straw hat to Monkey D. Luffy with the promise that it be returned when Monkey D. Luffy has become a great pirate.', E'Shanks entrusts his straw hat to Monkey D. Luffy with the promise that it be returned when Monkey D. Luffy has become a great pirate.', E'Shanks\nMonkey D. Luffy', E'Shanks entrusts his straw hat to Monkey D. Luffy with the promise that it be returned when Monkey D. Luffy has become a great pirate.', E'V7', E'Before the Red Hair Pirates leave Foosha Village forever, Shanks gives Monkey D. Luffy his straw hat, asking him to return it once he has become a great pirate.', E'open', NULL, NULL, E't2shanksentrustshisstrawhattomonkeyd.luffywiththepromisethatitbereturnedwhenmonkeyd.luffyhasbecomeagreatpirate.shanksentrustshisstrawhattomonkeyd.luffywiththepromisethatitbereturnedwhenmonkeyd.luffyhasbecomeagreatpirate.shanksmonkeyd.luffy약속1화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T3', 1, E'promise', E'약속', E'Monkey D. Luffy declares he will assemble a crew of about ten stronger than Shanks''s, get a pirate flag, gain the most treasure in the world, and become the Pirate King.', E'Monkey D. Luffy declares he will assemble a crew of about ten stronger than Shanks''s, get a pirate flag, gain the most treasure in the world, and become the Pirate King.', E'Monkey D. Luffy', E'Monkey D. Luffy declares he will assemble a crew of about ten stronger than Shanks''s, get a pirate flag, gain the most treasure in the world, and become the Pirate King.', E'V8', E'Ten years later a teenaged Monkey D. Luffy sails from Foosha Village, defeats the Lord of the Coast with Gomu Gomu no Pistol, and declares he will gather a crew of ten, get a flag, and become the Pirate King.', E'open', NULL, NULL, E't3monkeyd.luffydeclareshewillassembleacrewofabouttenstrongerthanshanks''s,getapirateflag,gainthemosttreasureintheworld,andbecomethepirateking.monkeyd.luffydeclareshewillassembleacrewofabouttenstrongerthanshanks''s,getapirateflag,gainthemosttreasureintheworld,andbecomethepirateking.monkeyd.luffy약속1화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T4', 1, E'unexplained_ability', E'설명 없는 능력', E'The Devil Fruits are a class of fruits, one of which grants rubber properties at the cost of never swimming again; the others are unspecified.', E'The Devil Fruits are a class of fruits, one of which grants rubber properties at the cost of never swimming again; the others are unspecified.', E'', E'The Devil Fruits are a class of fruits, one of which grants rubber properties at the cost of never swimming again; the others are unspecified.', E'V4', E'Monkey D. Luffy eats the Gomu Gomu no Mi from the Red Hair Pirates''s chest, gaining a rubber body and losing the ability to swim forever.', E'open', NULL, NULL, E't4thedevilfruitsareaclassoffruits,oneofwhichgrantsrubberpropertiesatthecostofneverswimmingagain;theothersareunspecified.thedevilfruitsareaclassoffruits,oneofwhichgrantsrubberpropertiesatthecostofneverswimmingagain;theothersareunspecified.설명없는능력1화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T5', 1, E'chekhovs_gun', E'체호프의 총', E'Monkey D. Luffy''s permanent inability to swim is emphasized repeatedly as the price of his power.', E'Monkey D. Luffy''s permanent inability to swim is emphasized repeatedly as the price of his power.', E'Monkey D. Luffy', E'Monkey D. Luffy''s permanent inability to swim is emphasized repeatedly as the price of his power.', E'V4', E'Monkey D. Luffy eats the Gomu Gomu no Mi from the Red Hair Pirates''s chest, gaining a rubber body and losing the ability to swim forever.', E'resolved', 66, E'Monkey D. Luffy''s inability to swim finally endangers him at the climax: netted above the ocean and then falling in after his winning blow, he is saved only by Sanji''s dive.', E't5monkeyd.luffy''spermanentinabilitytoswimisemphasizedrepeatedlyasthepriceofhispower.monkeyd.luffy''spermanentinabilitytoswimisemphasizedrepeatedlyasthepriceofhispower.monkeyd.luffy체호프의총1화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T6', 1, E'unexplained_ability', E'설명 없는 능력', E'Shanks scares off a giant sea monster with just a look, and calmly warns a gunman he is ''risking his life''', E'Shanks scares off a giant sea monster with just a look, and calmly warns a gunman he is ''risking his life'' — an unexplained aura of power.', E'Shanks\nLord of the Coast', E'Shanks scares off a giant sea monster with just a look, and calmly warns a gunman he is ''risking his life'' — an unexplained aura of power.', E'V6', E'At sea the Lord of the Coast devours Higuma and his boat; Shanks saves Monkey D. Luffy, losing his left arm to the creature and scaring it off with a look.', E'open', NULL, NULL, E't6shanksscaresoffagiantseamonsterwithjustalook,andcalmlywarnsagunmanheis''riskinghislife''shanksscaresoffagiantseamonsterwithjustalook,andcalmlywarnsagunmanheis''riskinghislife''—anunexplainedauraofpower.shankslordofthecoast설명없는능력1화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T7', 1, E'mentioned_unseen', E'언급만 됨', E'The Red Hair Pirates sail away from Foosha Village for the final time and do not return; Shanks''s whereabouts and one-armed fate are left open.', E'The Red Hair Pirates sail away from Foosha Village for the final time and do not return; Shanks''s whereabouts and one-armed fate are left open.', E'Shanks', E'The Red Hair Pirates sail away from Foosha Village for the final time and do not return; Shanks''s whereabouts and one-armed fate are left open.', E'V7', E'Before the Red Hair Pirates leave Foosha Village forever, Shanks gives Monkey D. Luffy his straw hat, asking him to return it once he has become a great pirate.', E'resolved', 96, E'Shanks reappears alive on an isolated island, revealed as ''The Red-Haired captain of Red Hair Pirates'', visited by Dracule Mihawk and celebrating Monkey D. Luffy''s first bounty.', E't7theredhairpiratessailawayfromfooshavillageforthefinaltimeanddonotreturn;shanks''swhereaboutsandone-armedfateareleftopen.theredhairpiratessailawayfromfooshavillageforthefinaltimeanddonotreturn;shanks''swhereaboutsandone-armedfateareleftopen.shanks언급만됨1화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T8', 1, E'chekhovs_gun', E'체호프의 총', E'The self-inflicted scar under Monkey D. Luffy''s left eye is given conspicuous attention as his mark of resolve.', E'The self-inflicted scar under Monkey D. Luffy''s left eye is given conspicuous attention as his mark of resolve.', E'Monkey D. Luffy', E'The self-inflicted scar under Monkey D. Luffy''s left eye is given conspicuous attention as his mark of resolve.', E'V2', E'To prove his toughness to the Red Hair Pirates, Monkey D. Luffy stabs himself with a knife below his left eye.', E'open', NULL, NULL, E't8theself-inflictedscarundermonkeyd.luffy''slefteyeisgivenconspicuousattentionashismarkofresolve.theself-inflictedscarundermonkeyd.luffy''slefteyeisgivenconspicuousattentionashismarkofresolve.monkeyd.luffy체호프의총1화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T9', 1, E'unexplained_ability', E'설명 없는 능력', E'Benn Beckman alone dispatches an entire armed bandit gang with a cigarette and rifle butt, stunning the villagers.', E'Benn Beckman alone dispatches an entire armed bandit gang with a cigarette and rifle butt, stunning the villagers.', E'Benn Beckman', E'Benn Beckman alone dispatches an entire armed bandit gang with a cigarette and rifle butt, stunning the villagers.', E'V5', E'After Higuma beats the captured Monkey D. Luffy, the Red Hair Pirates return; Lucky Roux shoots a bandit, Benn Beckman single-handedly routs the gang, and Higuma escapes with Monkey D. Luffy using a smoke bomb.', E'open', NULL, NULL, E't9bennbeckmanalonedispatchesanentirearmedbanditgangwithacigaretteandriflebutt,stunningthevillagers.bennbeckmanalonedispatchesanentirearmedbanditgangwithacigaretteandriflebutt,stunningthevillagers.bennbeckman설명없는능력1화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T10', 2, E'mentioned_unseen', E'언급만 됨', E'Roronoa Zoro, a famous bounty hunter feared even by Alvida, is talked about at length but never appears; Monkey D. Luffy sets out to recruit him.', E'Roronoa Zoro, a famous bounty hunter feared even by Alvida, is talked about at length but never appears; Monkey D. Luffy sets out to recruit him.', E'Roronoa Zoro\nMonkey D. Luffy', E'Roronoa Zoro, a famous bounty hunter feared even by Alvida, is talked about at length but never appears; Monkey D. Luffy sets out to recruit him.', E'V16', E'Monkey D. Luffy and Koby sail off together; on hearing more about Roronoa Zoro, Monkey D. Luffy decides to recruit him.', E'resolved', 3, E'Roronoa Zoro finally appears in person, bound in the 153rd Branch yard; Monkey D. Luffy and Koby meet and speak with him, though he initially refuses to join the crew.', E't10roronoazoro,afamousbountyhunterfearedevenbyalvida,istalkedaboutatlengthbutneverappears;monkeyd.luffysetsouttorecruithim.roronoazoro,afamousbountyhunterfearedevenbyalvida,istalkedaboutatlengthbutneverappears;monkeyd.luffysetsouttorecruithim.roronoazoromonkeyd.luffy언급만됨2화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T11', 2, E'promise', E'약속', E'Koby declares he would rather die escaping than remain with Alvida, and dreams of becoming a Marine who catches bad guys.', E'Koby declares he would rather die escaping than remain with Alvida, and dreams of becoming a Marine who catches bad guys.', E'Koby', E'Koby declares he would rather die escaping than remain with Alvida, and dreams of becoming a Marine who catches bad guys.', E'V13', E'Koby hides Monkey D. Luffy, shows him the boat he built over two years, and the two exchange dreams: Pirate King and Marine.', E'resolved', 7, E'Koby achieves his dream: rather than sail with the pirates, he provokes a public fight with Monkey D. Luffy to hide his pirate association and is accepted into the Marines, even if only to do chores.', E't11kobydeclareshewouldratherdieescapingthanremainwithalvida,anddreamsofbecomingamarinewhocatchesbadguys.kobydeclareshewouldratherdieescapingthanremainwithalvida,anddreamsofbecomingamarinewhocatchesbadguys.koby약속2화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T12', 2, E'chekhovs_gun', E'체호프의 총', E'Koby''s navigation knowledge is singled out as the one thing he is good at, the sole reason Alvida keeps him alive.', E'Koby''s navigation knowledge is singled out as the one thing he is good at, the sole reason Alvida keeps him alive.', E'Koby', E'Koby''s navigation knowledge is singled out as the one thing he is good at, the sole reason Alvida keeps him alive.', E'V10', E'Alvida beats a crewman over dust and forces Koby to declare her the most beautiful in the sea, then orders him to clean her shoes.', E'open', NULL, NULL, E't12koby''snavigationknowledgeissingledoutastheonethingheisgoodat,thesolereasonalvidakeepshimalive.koby''snavigationknowledgeissingledoutastheonethingheisgoodat,thesolereasonalvidakeepshimalive.koby체호프의총2화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T13', 2, E'mystery', E'수수께끼', E'Alvida has a bounty on her head that bounty hunter would come to claim, hinting at a wider bounty system tied to pirates.', E'Alvida has a bounty on her head that bounty hunter would come to claim, hinting at a wider bounty system tied to pirates.', E'Alvida', E'Alvida has a bounty on her head that bounty hunter would come to claim, hinting at a wider bounty system tied to pirates.', E'V12', E'Alvida hurls her club into the hideout; hearing an intruder, she fears the bounty hunter Roronoa Zoro has come for her bounty.', E'resolved', 96, E'The bounty system pays off on Monkey D. Luffy himself — the Marines issue his first wanted poster at 30,000,000, and Nami warns that everybody will now try to kill him.', E't13alvidahasabountyonherheadthatbountyhunterwouldcometoclaim,hintingatawiderbountysystemtiedtopirates.alvidahasabountyonherheadthatbountyhunterwouldcometoclaim,hintingatawiderbountysystemtiedtopirates.alvida수수께끼2화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T14', 3, E'promise', E'약속', E'Helmeppo announces he is going back on his promise to Roronoa Zoro and will have him executed in three days, setting a ticking clock; Monkey D. Luffy declares Roronoa Zoro is joining his crew.', E'Helmeppo announces he is going back on his promise to Roronoa Zoro and will have him executed in three days, setting a ticking clock; Monkey D. Luffy declares Roronoa Zoro is joining his crew.', E'Helmeppo\nRoronoa Zoro\nMonkey D. Luffy', E'Helmeppo announces he is going back on his promise to Roronoa Zoro and will have him executed in three days, setting a ticking clock; Monkey D. Luffy declares Roronoa Zoro is joining his crew.', E'V24', E'Helmeppo brags about breaking his promise and announces Roronoa Zoro will be executed in three days; Monkey D. Luffy punches him and decides Roronoa Zoro will join his crew.', E'resolved', 5, E'The three-day execution deadline is voided: Monkey D. Luffy frees Roronoa Zoro, blocks the Marines''s bullets, and Roronoa Zoro agrees to join his crew, though Morgan remains to be defeated.', E't14helmeppoannouncesheisgoingbackonhispromisetororonoazoroandwillhavehimexecutedinthreedays,settingatickingclock;monkeyd.luffydeclaresroronoazoroisjoininghiscrew.helmeppoannouncesheisgoingbackonhispromisetororonoazoroandwillhavehimexecutedinthreedays,settingatickingclock;monkeyd.luffydeclaresroronoazoroisjoininghiscrew.helmeppororonoazoromonkeyd.luffy약속3화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T15', 3, E'mystery', E'수수께끼', E'Roronoa Zoro refuses to become a criminal because he has ''his own dream'' to follow, which he does not explain.', E'Roronoa Zoro refuses to become a criminal because he has ''his own dream'' to follow, which he does not explain.', E'Roronoa Zoro', E'Roronoa Zoro refuses to become a criminal because he has ''his own dream'' to follow, which he does not explain.', E'V22', E'Roronoa Zoro refuses to join Monkey D. Luffy''s pirate crew, saying he has his own dream, then asks for the dirt-covered rice buggy balls and tells Monkey D. Luffy to say they were tasty.', E'resolved', 5, E'Roronoa Zoro''s dream is revealed in flashback: he swore with Kuina that one of them would become the world''s greatest swordsman, and carries her sword to fulfill it on her behalf.', E't15roronoazororefusestobecomeacriminalbecausehehas''hisowndream''tofollow,whichhedoesnotexplain.roronoazororefusestobecomeacriminalbecausehehas''hisowndream''tofollow,whichhedoesnotexplain.roronoazoro수수께끼3화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T16', 3, E'mentioned_unseen', E'언급만 됨', E'Morgan, the Marine in charge of the 153rd Branch, has a name that terrifies the townspeople as much as Roronoa Zoro''s, yet never appears; Koby cannot understand why they fear a Marine.', E'Morgan, the Marine in charge of the 153rd Branch, has a name that terrifies the townspeople as much as Roronoa Zoro''s, yet never appears; Koby cannot understand why they fear a Marine.', E'Morgan\nKoby', E'Morgan, the Marine in charge of the 153rd Branch, has a name that terrifies the townspeople as much as Roronoa Zoro''s, yet never appears; Koby cannot understand why they fear a Marine.', E'V18', E'In the town restaurant and street, mentioning the names Roronoa Zoro and Morgan provokes fearful reactions from the customers/villagers.', E'resolved', 4, E'Morgan finally appears at the 153rd Branch: a tyrant who extorts offerings, strikes his own son and subordinates, erects a statue of himself and orders a child killed for ''disrespect'' — explaining why the town fears him as much as Roronoa Zoro.', E't16morgan,themarineinchargeofthe153rdbranch,hasanamethatterrifiesthetownspeopleasmuchasroronoazoro''s,yetneverappears;kobycannotunderstandwhytheyfearamarine.morgan,themarineinchargeofthe153rdbranch,hasanamethatterrifiesthetownspeopleasmuchasroronoazoro''s,yetneverappears;kobycannotunderstandwhytheyfearamarine.morgankoby언급만됨3화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T17', 3, E'mystery', E'수수께끼', E'The Marine/Marines, supposedly lawmen who catch bad guys, behave cruelly and obey Helmeppo''s abuse of authority, shocking Koby whose dream is to join them.', E'The Marine/Marines, supposedly lawmen who catch bad guys, behave cruelly and obey Helmeppo''s abuse of authority, shocking Koby whose dream is to join them.', E'Koby\nHelmeppo', E'The Marine/Marines, supposedly lawmen who catch bad guys, behave cruelly and obey Helmeppo''s abuse of authority, shocking Koby whose dream is to join them.', E'V21', E'Helmeppo arrives with Marines, spits out and stomps the sugar-made rice buggy balls, cites his father''s law, and orders a Marine to throw Rika over the wall; Monkey D. Luffy catches her.', E'resolved', 7, E'With Morgan gone, the Marines prove honorable — they thank the pirates, decline to report them to Marine Headquarters, accept Koby despite his pirate past, and salute the departing pirates at the cost of a week without food, restoring Koby''s faith in the Marine.', E't17themarine/marines,supposedlylawmenwhocatchbadguys,behavecruellyandobeyhelmeppo''sabuseofauthority,shockingkobywhosedreamistojointhem.themarine/marines,supposedlylawmenwhocatchbadguys,behavecruellyandobeyhelmeppo''sabuseofauthority,shockingkobywhosedreamistojointhem.kobyhelmeppo수수께끼3화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T18', 3, E'chekhovs_gun', E'체호프의 총', E'Roronoa Zoro''s endurance is emphasized: bound without food for nine days, having struck some bargain/promise with Helmeppo that he would be freed if he survived.', E'Roronoa Zoro''s endurance is emphasized: bound without food for nine days, having struck some bargain/promise with Helmeppo that he would be freed if he survived.', E'Roronoa Zoro\nHelmeppo', E'Roronoa Zoro''s endurance is emphasized: bound without food for nine days, having struck some bargain/promise with Helmeppo that he would be freed if he survived.', E'V24', E'Helmeppo brags about breaking his promise and announces Roronoa Zoro will be executed in three days; Monkey D. Luffy punches him and decides Roronoa Zoro will join his crew.', E'resolved', 6, E'Roronoa Zoro survives his ordeal bound and starving; freed by Monkey D. Luffy, he immediately overpowers the entire Marines force despite his weakened state.', E't18roronoazoro''senduranceisemphasized:boundwithoutfoodforninedays,havingstrucksomebargain/promisewithhelmeppothathewouldbefreedifhesurvived.roronoazoro''senduranceisemphasized:boundwithoutfoodforninedays,havingstrucksomebargain/promisewithhelmeppothathewouldbefreedifhesurvived.roronoazorohelmeppo체호프의총3화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T24', 4, E'unexplained_ability', E'설명 없는 능력', E'Roronoa Zoro, starved and only just untied, gives a single threatening glance toward the 153rd Branch roof that is treated as menacing.', E'Roronoa Zoro, starved and only just untied, gives a single threatening glance toward the 153rd Branch roof that is treated as menacing.', E'Roronoa Zoro', E'Roronoa Zoro, starved and only just untied, gives a single threatening glance toward the 153rd Branch roof that is treated as menacing.', E'V33', E'Koby unties Roronoa Zoro and reveals his dream of being a just Marine and Monkey D. Luffy''s dream of becoming Pirate King; a Marines spots them and Koby is shot, prompting Roronoa Zoro to glare at the 153rd Branch roof.', E'resolved', 6, E'Roronoa Zoro''s menace is made good — once armed he immobilizes the whole Marines squad, terrifies them into tears, and personally defeats Morgan.', E't24roronoazoro,starvedandonlyjustuntied,givesasinglethreateningglancetowardthe153rdbranchroofthatistreatedasmenacing.roronoazoro,starvedandonlyjustuntied,givesasinglethreateningglancetowardthe153rdbranchroofthatistreatedasmenacing.roronoazoro설명없는능력4화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T34', 7, E'mentioned_unseen', E'언급만 됨', E'Marine Headquarters, the higher authority the Marines choose not to report Morgan''s defeat to, is named but unseen.', E'Marine Headquarters, the higher authority the Marines choose not to report Morgan''s defeat to, is named but unseen.', E'', E'Marine Headquarters, the higher authority the Marines choose not to report Morgan''s defeat to, is named but unseen.', E'V51', E'The Marines confirm Monkey D. Luffy and Roronoa Zoro are pirates, thank them for their help, order them to leave town, but promise not to report the incident to Marine Headquarters.', E'resolved', 94, E'Marine Headquarters finally enters the story indirectly: Nezumi alerts Marine marine headquarters about the Straw Hat Crew at the 16th 153rd branch.', E't34marineheadquarters,thehigherauthoritythemarineschoosenottoreportmorgan''sdefeatto,isnamedbutunseen.marineheadquarters,thehigherauthoritythemarineschoosenottoreportmorgan''sdefeatto,isnamedbutunseen.언급만됨7화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T374', 96, E'promise', E'약속', E'Dracule Mihawk tells Shanks of Monkey D. Luffy''s first bounty, recalling Shanks''s story about a kid in a little village; Shanks, eager to meet Monkey D. Luffy again, throws a party in celebration.', E'Dracule Mihawk tells Shanks of Monkey D. Luffy''s first bounty, recalling Shanks''s story about a kid in a little village; Shanks, eager to meet Monkey D. Luffy again, throws a party in celebration.', E'Shanks\nDracule Mihawk\nMonkey D. Luffy', E'Dracule Mihawk tells Shanks of Monkey D. Luffy''s first bounty, recalling Shanks''s story about a kid in a little village; Shanks, eager to meet Monkey D. Luffy again, throws a party in celebration.', E'V676', E'On an isolated island Dracule Mihawk finds Shanks, the red-haired captain of the Red Hair Pirates, and tells him of Monkey D. Luffy''s first wanted poster, recalling Shanks''s story about a kid in a little village; Shanks throws a party in celebration.', E'open', NULL, NULL, E't374draculemihawktellsshanksofmonkeyd.luffy''sfirstbounty,recallingshanks''sstoryaboutakidinalittlevillage;shanks,eagertomeetmonkeyd.luffyagain,throwsapartyincelebration.draculemihawktellsshanksofmonkeyd.luffy''sfirstbounty,recallingshanks''sstoryaboutakidinalittlevillage;shanks,eagertomeetmonkeyd.luffyagain,throwsapartyincelebration.shanksdraculemihawkmonkeyd.luffy약속96화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T378', 97, E'chekhovs_gun', E'체호프의 총', E'Sandai Kitetsu is a cursed blade whose every previous wielder died a tragic death; Roronoa Zoro takes it after it refuses to cut him, and Ipponmatsu says the sword chose him.', E'Sandai Kitetsu is a cursed blade whose every previous wielder died a tragic death; Roronoa Zoro takes it after it refuses to cut him, and Ipponmatsu says the sword chose him.', E'Roronoa Zoro\nIpponmatsu', E'Sandai Kitetsu is a cursed blade whose every previous wielder died a tragic death; Roronoa Zoro takes it after it refuses to cut him, and Ipponmatsu says the sword chose him.', NULL, E'', E'resolved', 108, E'Partially paid off: Roronoa Zoro takes Sandai Kitetsu into its first battle and finds it ''remarkably sharp'' — it cuts clean through a stone hammer. No tragic consequence of the curse yet appears, so the curse itself remains untested.', E't378sandaikitetsuisacursedbladewhoseeverypreviouswielderdiedatragicdeath;roronoazorotakesitafteritrefusestocuthim,andipponmatsusaystheswordchosehim.sandaikitetsuisacursedbladewhoseeverypreviouswielderdiedatragicdeath;roronoazorotakesitafteritrefusestocuthim,andipponmatsusaystheswordchosehim.roronoazoroipponmatsu체호프의총97화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T467', 117, E'chekhovs_gun', E'체호프의 총', E'Monkey D. Luffy hands his treasured straw hat to Nefertari Vivi before fighting Dorry, over her protests.', E'Monkey D. Luffy hands his treasured straw hat to Nefertari Vivi before fighting Dorry, over her protests.', E'Monkey D. Luffy\nNefertari Vivi', E'Monkey D. Luffy hands his treasured straw hat to Nefertari Vivi before fighting Dorry, over her protests.', E'V802', E'Dorry''s rum explodes as he drinks it, gravely injuring him; he blames Monkey D. Luffy and Nefertari Vivi. Monkey D. Luffy hands his straw hat to Nefertari Vivi and goes to fight the giant despite her pleas.', E'open', NULL, NULL, E't467monkeyd.luffyhandshistreasuredstrawhattonefertarivivibeforefightingdorry,overherprotests.monkeyd.luffyhandshistreasuredstrawhattonefertarivivibeforefightingdorry,overherprotests.monkeyd.luffynefertarivivi체호프의총117화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T1575', 386, E'chekhovs_gun', E'체호프의 총', E'The Golden Den Den Mushi: a rank-restricted snail device given to Spandam by Admiral Kuzan that activates the Buster Call, with a button on its shell that destroys an entire island at one push. Spandam nearly presses it by accident when startled, and gloats about authority used as a weapon.', E'The Golden Den Den Mushi: a rank-restricted snail device given to Spandam by Admiral Kuzan that activates the Buster Call, with a button on its shell that destroys an entire island at one push. Spandam nearly presses it by accident when startled, and gloats about authority used as a weapon.', E'Spandam\nVice Admiral Kuzan', E'The Golden Den Den Mushi: a rank-restricted snail device given to Spandam by Admiral Kuzan that activates the Buster Call, with a button on its shell that destroys an entire island at one push. Spandam nearly presses it by accident when startled, and gloats about authority used as a weapon.', E'V2534', E'In the Tower of Justice, Spandam shows Funkfreed the Golden Den Den Mushi, boasting that it activates the Buster Call, that Kuzan gave it to him, that one push of its button destroys an island, and that if the Ancient Weapons is revived he will command the Buster Call and run the Marines.', E'open', NULL, NULL, E't1575thegoldendendenmushi:arank-restrictedsnaildevicegiventospandambyadmiralkuzanthatactivatesthebustercall,withabuttononitsshellthatdestroysanentireislandatonepush.spandamnearlypressesitbyaccidentwhenstartled,andgloatsaboutauthorityusedasaweapon.thegoldendendenmushi:arank-restrictedsnaildevicegiventospandambyadmiralkuzanthatactivatesthebustercall,withabuttononitsshellthatdestroysanentireislandatonepush.spandamnearlypressesitbyaccidentwhenstartled,andgloatsaboutauthorityusedasaweapon.spandamviceadmiralkuzan체호프의총386화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
INSERT INTO foreshadowings (thread_id, start_chapter, thread_type, thread_kind, title, fact, thread_related_people, excerpt, scene, scene_excerpt, status, resolved_chapter, resolution, search_text, state_digest, cards_digest) VALUES (E'T1648', 400, E'promise', E'약속', E'The crew scatters into simultaneous duels: Franky vs Fukurou, Sogeking vs Jabra, Nami vs Kumadori, Sanji vs Kalifa, Roronoa Zoro vs Kaku, Monkey D. Luffy vs Rob Lucci.', E'The crew scatters into simultaneous duels: Franky vs Fukurou, Sogeking vs Jabra, Nami vs Kumadori, Sanji vs Kalifa, Roronoa Zoro vs Kaku, Monkey D. Luffy vs Rob Lucci.', E'Franky\nFukurou\nSogeking\nJabra\nNami\nKumadori\nSanji\nKalifa\nRoronoa Zoro\nKaku\nMonkey D. Luffy\nRob Lucci', E'The crew scatters into simultaneous duels: Franky vs Fukurou, Sogeking vs Jabra, Nami vs Kumadori, Sanji vs Kalifa, Roronoa Zoro vs Kaku, Monkey D. Luffy vs Rob Lucci.', E'V2658', E'The crew scatters through the Tower of Justice and each meets a CP9 member: Fukurou ambushes Franky in the kitchen, Sogeking finds Jabra asleep beside a key, Kumadori confronts Nami in the basement, Kalifa traps Sanji over tea, and Kaku awaits Roronoa Zoro by the fireplace.', E'open', NULL, NULL, E't1648thecrewscattersintosimultaneousduels:frankyvsfukurou,sogekingvsjabra,namivskumadori,sanjivskalifa,roronoazorovskaku,monkeyd.luffyvsroblucci.thecrewscattersintosimultaneousduels:frankyvsfukurou,sogekingvsjabra,namivskumadori,sanjivskalifa,roronoazorovskaku,monkeyd.luffyvsroblucci.frankyfukurousogekingjabranamikumadorisanjikalifaroronoazorokakumonkeyd.luffyroblucci약속400화', E'139d61c9b7c7f9adc8768fa7a74eceb2a571c20c1f714f7bbe4804a6d2692b8e', E'49700cffb2ae94c713d9f16fc7a2dbdad68974f010d7e2643a6c8332e5a06fca');
